CREATE DATABASE IF NOT EXISTS agro_smart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE agro_smart;
CREATE TABLE tenants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,status ENUM('trial','active','suspended','cancelled') NOT NULL DEFAULT 'trial',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('owner','admin','manager','operator','viewer') NOT NULL DEFAULT 'operator',status ENUM('active','invited','disabled') NOT NULL DEFAULT 'active',last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_user_email(tenant_id,email),INDEX(tenant_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE farms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,province VARCHAR(100),district VARCHAR(100),address VARCHAR(255),latitude DECIMAL(10,7),longitude DECIMAL(10,7),status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE animals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NOT NULL,tag_code VARCHAR(100) NOT NULL,species ENUM('poultry','cattle','goat','pig','sheep','fish','other') NOT NULL,breed VARCHAR(100),sex ENUM('male','female','unknown') DEFAULT 'unknown',birth_date DATE,status ENUM('active','sold','deceased','transferred') DEFAULT 'active',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_animal_tag(tenant_id,tag_code),INDEX(tenant_id,farm_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE devices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NULL,device_code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,device_type VARCHAR(80) NOT NULL DEFAULT 'esp32',status ENUM('active','inactive','maintenance') DEFAULT 'active',firmware_version VARCHAR(50),last_seen_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE device_credentials(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,device_id BIGINT UNSIGNED NOT NULL,secret_hash CHAR(64) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,revoked_at DATETIME NULL,UNIQUE KEY uq_device_secret(device_id),FOREIGN KEY(device_id) REFERENCES devices(id));
CREATE TABLE telemetry(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,device_id BIGINT UNSIGNED NOT NULL,temperature DECIMAL(6,2),humidity DECIMAL(6,2),feed_level_kg DECIMAL(8,2),water_level_pct DECIMAL(6,2),battery_voltage DECIMAL(6,2),raw_payload JSON,recorded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,recorded_at),INDEX(device_id,recorded_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(device_id) REFERENCES devices(id));
CREATE TABLE device_commands(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,device_id BIGINT UNSIGNED NOT NULL,created_by BIGINT UNSIGNED NULL,command_type ENUM('dispense_feed','fan_on','fan_off','lamp_on','lamp_off') NOT NULL,payload JSON NOT NULL,status ENUM('queued','sent','executed','failed','expired') NOT NULL DEFAULT 'queued',idempotency_key VARCHAR(100),result_message VARCHAR(500),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME,completed_at DATETIME,expires_at DATETIME NOT NULL,UNIQUE KEY uq_command_idem(tenant_id,idempotency_key),INDEX(device_id,status,created_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(device_id) REFERENCES devices(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NULL,device_id BIGINT UNSIGNED NULL,severity ENUM('info','warning','critical') NOT NULL DEFAULT 'warning',title VARCHAR(180) NOT NULL,message TEXT NOT NULL,status ENUM('open','acknowledged','resolved') NOT NULL DEFAULT 'open',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,resolved_at DATETIME,INDEX(tenant_id,status,created_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE alert_rules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,metric VARCHAR(50) NOT NULL,operator VARCHAR(5) NOT NULL,threshold DECIMAL(12,4) NOT NULL,severity ENUM('info','warning','critical') DEFAULT 'warning',enabled TINYINT(1) DEFAULT 1,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE expenses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NULL,category VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(14,2) NOT NULL,currency CHAR(3) DEFAULT 'MZN',expense_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE revenues(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,farm_id BIGINT UNSIGNED NULL,category VARCHAR(100) NOT NULL,description VARCHAR(255) NOT NULL,amount DECIMAL(14,2) NOT NULL,currency CHAR(3) DEFAULT 'MZN',revenue_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE plans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,monthly_price_mzn DECIMAL(12,2) NOT NULL,max_farms INT UNSIGNED NOT NULL,max_devices INT UNSIGNED NOT NULL,max_users INT UNSIGNED NOT NULL DEFAULT 5,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,plan_id BIGINT UNSIGNED NOT NULL,status ENUM('trial','active','past_due','cancelled') DEFAULT 'trial',starts_at DATETIME NOT NULL,ends_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(plan_id) REFERENCES plans(id));
CREATE TABLE subscription_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,subscription_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,currency CHAR(3) DEFAULT 'MZN',provider VARCHAR(50),provider_reference VARCHAR(150),status ENUM('pending','paid','failed','refunded') DEFAULT 'pending',paid_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(subscription_id) REFERENCES subscriptions(id));
CREATE TABLE invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,subscription_id BIGINT UNSIGNED,number VARCHAR(50) NOT NULL UNIQUE,amount DECIMAL(12,2) NOT NULL,currency CHAR(3) DEFAULT 'MZN',status ENUM('draft','issued','paid','void') DEFAULT 'issued',due_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,channel ENUM('in_app','email','sms','whatsapp') DEFAULT 'in_app',subject VARCHAR(180),message TEXT NOT NULL,status ENUM('queued','sent','failed') DEFAULT 'queued',sent_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45),meta JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,created_at),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NULL,revoked_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(user_id) REFERENCES users(id));
INSERT INTO plans(code,name,monthly_price_mzn,max_farms,max_devices,max_users) VALUES ('basic','Básico',1500,1,3,3),('pro','Pro',2500,5,15,10),('enterprise','Enterprise',7500,100,500,100);
